<?php
namespace App\Http\Controllers;
use App\Models\{Favorite,User,UserNotification,SavedMarket,Market};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Hash;
class CustomerController extends Controller {
    public function dashboard(){
        $u=auth()->user();$stats=['orders'=>$u->customerOrders()->count(),'pending'=>$u->customerOrders()->where('status','placed')->count(),'accepted'=>$u->customerOrders()->where('status','accepted')->count(),'ready'=>$u->customerOrders()->where('status','ready')->count(),'completed'=>$u->customerOrders()->where('status','completed')->count(),'favorites'=>Favorite::where('user_id',$u->id)->count(),'saved_markets'=>SavedMarket::where('customer_id',$u->id)->count(),'spent'=>$u->customerOrders()->where('status','completed')->sum('total_amount')];
        $latestOrders=$u->customerOrders()->with(['items.product','farmer','market'])->latest()->take(6)->get();$notifications=UserNotification::where('user_id',$u->id)->whereNull('read_at')->latest()->take(5)->get();
        $recentIds=collect(session('marketlink_recent_products',[]))->take(4);$recentProducts=$recentIds->isEmpty()?collect():\App\Models\Product::with(['category','farmer'])->whereIn('id',$recentIds)->get()->sortBy(fn($p)=>array_search($p->id,$recentIds->all()))->values();
        $recommended=\App\Models\Product::with(['category','farmer'])->withAvg('reviews','rating')->where('is_available',1)->where('stock_quantity','>',0)->orderByDesc('reviews_avg_rating')->latest()->take(4)->get();
        return view('customer.dashboard',compact('stats','latestOrders','notifications','recentProducts','recommended')); }
    public function profile(){return view('customer.profile',['user'=>auth()->user()]);}
    public function updateProfile(Request $request){$data=$request->validate(['name'=>['required','string','max:120'],'phone'=>['nullable','string','max:30'],'address'=>['nullable','string','max:255'],'password'=>['nullable','string','min:8','confirmed']]);$user=auth()->user();$user->update(['name'=>$data['name'],'phone'=>$data['phone']??null,'address'=>$data['address']??null]);if(!empty($data['password']))$user->update(['password'=>Hash::make($data['password'])]);return back()->with('success','Profile updated successfully.');}
    public function favorites(){ $favorites=Favorite::with(['product.category','product.market','product.farmer.farmerProfile','farmer.farmerProfile'])->where('user_id',auth()->id())->latest()->get();return view('customer.favorites',compact('favorites')); }
    public function toggleFavorite(Request $request){$data=$request->validate(['product_id'=>'nullable|exists:products,id','farmer_id'=>'nullable|exists:users,id']);if(empty($data['product_id'])&&empty($data['farmer_id']))abort(422,'Choose a product or farmer.');if(!empty($data['farmer_id']))abort_unless(User::whereKey($data['farmer_id'])->where('role','farmer')->exists(),422,'Invalid farmer.');$query=Favorite::where('user_id',auth()->id())->when($data['product_id']??null,fn($q)=>$q->where('product_id',$data['product_id']),fn($q)=>$q->whereNull('product_id'))->when($data['farmer_id']??null,fn($q)=>$q->where('farmer_id',$data['farmer_id']),fn($q)=>$q->whereNull('farmer_id'));if($query->exists()){$query->delete();return back()->with('success','Removed from favorites.');}Favorite::create(['user_id'=>auth()->id(),'product_id'=>$data['product_id']??null,'farmer_id'=>$data['farmer_id']??null]);return back()->with('success','Saved to favorites.');}
    public function markets(){ $saved=SavedMarket::with('market')->where('customer_id',auth()->id())->latest()->get();$markets=Market::where('is_active',1)->orderBy('name')->get();return view('customer.markets',compact('saved','markets')); }
    public function toggleMarket(Market $market){abort_unless($market->is_active,404);$q=SavedMarket::where('customer_id',auth()->id())->where('market_id',$market->id);if($q->exists()){$q->delete();return back()->with('success','Market removed from saved markets.');}SavedMarket::create(['customer_id'=>auth()->id(),'market_id'=>$market->id]);return back()->with('success','Market saved.');}
    public function notifications(){return view('customer.notifications',['notifications'=>UserNotification::where('user_id',auth()->id())->latest()->paginate(15)]);}
    public function markNotificationRead(UserNotification $notification){abort_unless($notification->user_id===auth()->id(),403);$notification->update(['read_at'=>now()]);return back();}
    public function markAllNotificationsRead(){UserNotification::where('user_id',auth()->id())->whereNull('read_at')->update(['read_at'=>now()]);return back()->with('success','All notifications marked as read.');}
    public function exportOrders(){ $orders=auth()->user()->customerOrders()->with(['farmer','market','items.product'])->latest()->get();return response()->streamDownload(function()use($orders){$o=fopen('php://output','w');fputcsv($o,['Order','Farmer','Market','Pickup Date','Status','Items','Total']);foreach($orders as $ord)fputcsv($o,[$ord->order_number,$ord->farmer->name,$ord->market?->name,$ord->pickup_date->format('Y-m-d'),$ord->status,$ord->items->pluck('product.name')->join(' | '),$ord->total_amount]);fclose($o);},'marketlink-my-orders.csv',['Content-Type'=>'text/csv']);}
}
